{"hypotheses": [
  {
    "name": "Intangible Innovation Synergy",
    "mechanism": "Firms with both intense R&D activity (RD) and high brand investment (BrandInvest) harness intangible capital more effectively, creating a competitive edge underappreciated by traditional metrics. By combining these, the composite captures synergistic value from complementary intangible assets, which are rewarded especially when markets struggle to price such complexity.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "RD"},
        {"weight": 1.0, "primitive": "BrandInvest"},
        {"weight": -0.5, "primitive": "PatentsRD"}
      ],
      "regime": "TERM_SPREAD_POSITIVE",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_POSITIVE", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "correlation", "primitive": "IntanBM", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.85,
    "expected_decay_half_life_months": 36
  },
  {
    "name": "Analyst Dispersion Uncertainty Premium",
    "mechanism": "Stocks with high EPS forecast dispersion (ForecastDispersion) but also positive recent earnings surprises (EarningsSurprise) reflect underpriced uncertainty resolved favorably. When coupled with high institutional ownership turnover (RIO_Turnover), it signals informed risk-taking, capturing an uncertainty premium not present in the primitives individually.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "ForecastDispersion"},
        {"weight": 1.0, "primitive": "EarningsSurprise"},
        {"weight": 0.5, "primitive": "RIO_Turnover"}
      ],
      "regime": "VIX_ABOVE_TRAILING_MEDIAN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_ABOVE_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "correlation", "primitive": "AnalystRevision", "bound": "below", "threshold": 0.3},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.7,
    "expected_decay_half_life_months": 18
  },
  {
    "name": "Volatility Sentiment Disconnect",
    "mechanism": "Stocks with rising call option volume (dVolCall) but falling realized volatility (RealizedVol) and wide bid-ask spreads (BidAskSpread) indicate sentiment-driven mispricing in quiet markets. This composite targets returns from sentiment shocks not captured by any single volatility or liquidity measure.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "dVolCall"},
        {"weight": -1.0, "primitive": "RealizedVol"},
        {"weight": 0.5, "primitive": "BidAskSpread"}
      ],
      "regime": "MKT_TRAILING_12M_UP",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_UP", "direction": "higher"},
      {"type": "size_segment", "segment": "micro", "direction": "stronger"},
      {"type": "international", "region": "emerging", "direction": "same_sign"}
    ],
    "expected_annualized_sharpe": 0.6,
    "expected_decay_half_life_months": 30
  },
  {
    "name": "Leverage-Accrual Stress Indicator",
    "mechanism": "Firms with rising accruals (Accruals) and simultaneously increasing market leverage (Leverage) are more likely to engage in aggressive accounting under financial distress, leading to future underperformance. The combination captures distress risk more precisely than either primitive alone.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "Accruals"},
        {"weight": 1.0, "primitive": "Leverage"},
        {"weight": -0.5, "primitive": "OScore"}
      ],
      "regime": "TERM_SPREAD_NEGATIVE",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_NEGATIVE", "direction": "higher"},
      {"type": "correlation", "primitive": "TotalAccruals", "bound": "below", "threshold": 0.3},
      {"type": "size_segment", "segment": "mega", "direction": "weaker"}
    ],
    "expected_annualized_sharpe": 0.8,
    "expected_decay_half_life_months": 24
  },
  {
    "name": "Competitive Powerhouse",
    "mechanism": "High product market concentration (Herf) combined with robust cash-based operating profitability (CBOperProf) and declining analyst coverage (ChNAnalyst) identifies firms that are both dominant and underanalyzed, capturing persistent mispricing due to investor inattention in powerful incumbents.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "Herf"},
        {"weight": 1.0, "primitive": "CBOperProf"},
        {"weight": 0.5, "primitive": "ChNAnalyst"}
      ],
      "regime": "VIX_BELOW_TRAILING_MEDIAN",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_BELOW_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"}
    ],
    "expected_annualized_sharpe": 0.75,
    "expected_decay_half_life_months": 48
  },
  {
    "name": "Financial Engineering Caution",
    "mechanism": "Stocks with rising share repurchases (ShareRepurchase) but also rising net debt to price (NetDebtPrice) and increased convertible debt (ConvDebt) are engaging in financial engineering that often precedes weaker long-term returns. The composite signals aggressive capital structure management overlooked by investors focused on buybacks alone.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "ShareRepurchase"},
        {"weight": -1.0, "primitive": "NetDebtPrice"},
        {"weight": -0.5, "primitive": "ConvDebt"}
      ],
      "regime": "MKT_TRAILING_12M_DOWN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_DOWN", "direction": "higher"},
      {"type": "size_segment", "segment": "mega", "direction": "weaker"},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.7,
    "expected_decay_half_life_months": 20
  },
  {
    "name": "Customer-Supplier Momentum Spread",
    "mechanism": "Stocks that are simultaneously favored by customer momentum (iomom_cust) but disfavored by supplier momentum (iomom_supp) reflect asymmetric value chain shocks: positive demand-side news not yet matched by supply chain optimism. The composite captures supply-demand propagation timing ignored by simple momentum factors.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "iomom_cust"},
        {"weight": -1.0, "primitive": "iomom_supp"}
      ],
      "regime": "null",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"},
      {"type": "correlation", "primitive": "IndMom", "bound": "below", "threshold": 0.3},
      {"type": "size_segment", "segment": "small", "direction": "stronger"}
    ],
    "expected_annualized_sharpe": 0.65,
    "expected_decay_half_life_months": 36
  },
  {
    "name": "IPO Organizational Capital Payoff",
    "mechanism": "Younger IPO firms (AgeIPO) with high organizational capital (OrgCap) but low tangibility (tang) are better at deploying new business models with fewer physical constraints, enabling dynamic growth not captured by examining age or asset composition alone. The premium accrues as these firms scale efficiently.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "AgeIPO"},
        {"weight": 1.0, "primitive": "OrgCap"},
        {"weight": -0.5, "primitive": "tang"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "international", "region": "emerging", "direction": "same_sign"},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.8,
    "expected_decay_half_life_months": null
  }
]}
